"""Isolated dotenv-value parser adapted from the repository preflight reader."""

import re


def parse_value(key, value):
    if value[:1] in "\"'":
        quote = value[0]
        closing = value.find(quote, 1)
        if closing == -1:
            raise ValueError(f"{key} has an unterminated quote")
        inner = value[1:closing]
        rest = value[closing + 1:].strip()
        if rest and not rest.startswith("#"):
            raise ValueError(f"{key} has text after its closing quote")
        if quote == '\"' and "$" in inner:
            raise ValueError("Interpolated values are unsupported")
        return inner
    value = re.split(r"\s+#", value, maxsplit=1)[0].strip()
    if "$" in value:
        raise ValueError("Interpolated values are unsupported")
    return value


def handle(value):
    entries = {}
    for raw_line in value["text"].splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[7:].lstrip()
        key, separator, raw_value = line.partition("=")
        key = key.strip()
        if not separator or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
            continue
        entries[key] = parse_value(key, raw_value.strip())
    return {"entries": entries}

