import unittest

from component import handle


class ConfigurationReaderTests(unittest.TestCase):
    def test_normal_values_and_comments(self):
        self.assertEqual(
            handle({"text": "# comment\nALPHA=ready # note\nexport BETA=two\n"}),
            {"entries": {"ALPHA": "ready", "BETA": "two"}},
        )

    def test_quoted_literals(self):
        self.assertEqual(
            handle({"text": "VALUE=' padded $literal ' # note\nEMPTY=''\n"}),
            {"entries": {"VALUE": " padded $literal ", "EMPTY": ""}},
        )


if __name__ == "__main__":
    unittest.main()
